import 'dart:convert';
import 'dart:typed_data';

/// Logo ICP-Brasil congelado para que a assinatura nunca dependa da rede.
///
/// Fonte: https://certisign.com.br/wp-content/uploads/2025/06/ICP-BRASIL.png
Uint8List icpBrasilLogoPngBytes() => base64Decode(
      '${_icpBrasilLogoPngBase64.substring(0, 3865)}'
      'qNkMEoGo2QwSgajZDBKB'
      '${_icpBrasilLogoPngBase64.substring(3865)}',
    );

const String _icpBrasilLogoPngBase64 =
    '';
